svg.metadata:
flowchart TB
  A["Edit filters; Search / Enter / page / sort"]
  B["Controller: issue request; mark latest sequence"]
  C["loading: keep previous data when available"]
  D{"Is this still the latest request?"}
  E["Success: update rows; loaded=true"]
  F["Failure: error / retry; preserve previous data"]
  G["Late response: ignore without overwriting new state"]
  A -->|"submit action"| B
  B --> C
  C --> D
  D -->|"yes; success"| E
  D -->|"yes; failure"| F
  D -->|"no"| G
  F -->|"user retries"| B
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class C,F,G pending;
